import{_ as l,l as o,o as a,c as n,v as i,p as s,x as t,d,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"缺陷复检与分类","description":"","frontmatter":{"title":"缺陷复检与分类","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/defect-review-classification.md","filePath":"litho/defect-review-classification.md","lastUpdated":1789023840000}'),p={name:"litho/defect-review-classification.md"};function E(h,e,_,f,D,C){const r=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=i('<h1 id="缺陷复检与分类" tabindex="-1">缺陷复检与分类 <a class="header-anchor" href="#缺陷复检与分类" aria-label="Permalink to &quot;缺陷复检与分类&quot;">​</a></h1><div class="epigraph"><p>检测给出坐标与模糊斑；复检 SEM 才把斑变成桥、颗粒、残胶或假点。分错类，Pareto 就会把轨道和 OPC 的人派错房间。</p><footer>—— 对照缺陷复检（review SEM）与 ADC 自动分类的产线通称</footer></div><p><a href="/litho/defect-inspection-optical-ebeam">上一课</a>找到候选。缺口是标签：自动分类（ADC）快而错，人工 SEM 慢而准。本课钉复检与分类。良率如何随时间被这些标签推着学，留给[下一课](/litho/yield-learning-curve）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分类树：颗粒（来源：轨道、扫描机、刻蚀、环境）、图案缺陷（桥、断、缺孔）、残留、划伤、假点（颜色噪声、充电）。系统热点在复检里长得一样并对齐设计。ADC 用光学图像训练，换层换配方即漂移，必须抽检人工黄金集。</p><p>缺口是<strong>行动映射</strong>，不是再买一台 review SEM。每类对应责任：轨道缺陷 → 涂胶/显影；图案 → OPC/PWQ；缺孔 → 随机窗/剂量；金属颗粒 → 刻蚀/CMP。分派用的 killer / nuisance 划分也在此：nuisance 进规格但不挡批，killer 扣留。</p><h3 id="假点会毒死学习曲线" tabindex="-1">假点会毒死学习曲线 <a class="header-anchor" href="#假点会毒死学习曲线" aria-label="Permalink to &quot;假点会毒死学习曲线&quot;">​</a></h3><p>假点当 killer，重工爆炸、学习曲线假装「缺陷很多」。阈值过严则漏 killer。黄金集与计量匹配同样要版本化。</p><p><span class="marginnote">SEM 复检会收缩胶、污染热点。ADI 复检策略要限制剂量与次数，尤其 EUV 薄胶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：检测 → ADC 预分类 → 抽样复检 SEM → 修正 ADC → 更新 Pareto。与设计：图案类回写热点库（匹配课）。与 FDC：某类突然升，对设备事件。与客户失效：测试失败位的复检是另一条链，本课只要求能 join 坐标。</p><p>黄金集按层、按配方版本保存，定期盲测 ADC。分类漂移是学习曲线假平台的常见原因：其实是标签乱了，不是缺陷没了。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学斑欠定，多种物理共像。SEM 高分辨闭合。ADC 是该层光学外观的分类器，不是物理因果模型——与 VM 同一限制。人工偏差（班次）要用黄金片监控。</p>',14)),(a(),s(A,null,{default:t(()=>[c(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20INSP%5B%22%E6%A3%80%E6%B5%8B%E6%96%91%22%5D%20--%3E%20ADC%5B%22%E8%87%AA%E5%8A%A8%E5%88%86%E7%B1%BB%22%5D%0A%20%20ADC%20--%3E%20REV%5B%22SEM%20%E5%A4%8D%E6%A3%80%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20REV%20--%3E%20GOLD%5B%22%E9%BB%84%E9%87%91%E9%9B%86%E6%A0%A1%E5%87%86%20ADC%22%5D%0A%20%20REV%20--%3E%20PAR%5B%22%E5%8F%AF%E8%A1%8C%E5%8A%A8%20Pareto%22%5D%0A%20%20PAR%20--%3E%20OWN%5B%22%E8%BD%A8%E9%81%93%20%2F%20OPC%20%2F%20%E5%88%BB%E8%9A%80%20%2F%20%E9%9A%8F%E6%9C%BA%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<p>ADC 校准靠黄金集。假点当 killer 会毒死学习曲线，阈值过严则漏掉真桥连。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写商业 ADC 准确率数字。不把分类当失效分析 TEM（末课）。CSAM 等封装检测不在此。</p><p>后课默认：Pareto 基于复检校准的类。下一课用这本账画学习曲线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复检把检测斑变成可行动类；ADC 必须靠黄金集防漂移。</li><li>killer/nuisance 划分进分派。</li><li>图案类回写热点库。</li><li>出处：review SEM 与 ADC 产线通称；缺陷分类工程实践。</li></ul>',6))])}const P=l(p,[["render",E]]);export{m as __pageData,P as default};
